  <details class="ext-settings-accordion" id="settingsConfluenceGroup" data-requirement="required"><summary><span>Confluence Space Discovery</span><span class="ext-settings-badge" id="settingsConfluenceGroupState" data-state="required">Required</span></summary><div class="ext-settings-content"><section><div class="guide-token-links"><button id="guideConfluenceTokenLink" type="button" class="guide-token-link">Get Confluence API token ↗</button></div><div class="gate-search-bar"><input type="search" id="settingsSpaceQuery" minlength="2" maxlength="120" placeholder="Space name or key" aria-label="Search Confluence spaces"/><button type="button" id="settingsSpaceSearch" class="secondary">Search</button></div><p class="muted" id="settingsSpaceMessage" role="status">Enter a space name or key to search.</p>${spaceTable('settingsSpaces')}</section></div></details>
